import{_ as a,o as e,c as r,a4 as d}from"./chunks/framework.cM03Lg2X.js";const b=JSON.parse('{"title":"训练与推理系统","description":"分布式训练、后训练、推理调度、缓存与模型压缩的工程地图。","frontmatter":{"title":"训练与推理系统","description":"分布式训练、后训练、推理调度、缓存与模型压缩的工程地图。"},"headers":[],"relativePath":"ai-infra/training-inference.md","filePath":"ai-infra/training-inference.md","lastUpdated":1786332289000}'),n={name:"ai-infra/training-inference.md"};function i(l,t,o,h,s,c){return e(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="训练与推理系统" tabindex="-1">训练与推理系统 <a class="header-anchor" href="#训练与推理系统" aria-label="Permalink to “训练与推理系统”">​</a></h1><p>训练追求稳定地完成大量并行计算，推理追求在动态请求下平衡延迟、吞吐和成本。两者共享模型与硬件，但工作负载并不相同，不能把训练优化原样搬到线上服务。</p><h2 id="分布式训练-四种切分方式" tabindex="-1">分布式训练：四种切分方式 <a class="header-anchor" href="#分布式训练-四种切分方式" aria-label="Permalink to “分布式训练：四种切分方式”">​</a></h2><table tabindex="0"><thead><tr><th>策略</th><th>切分对象</th><th>适合解决</th><th>典型代价</th></tr></thead><tbody><tr><td>数据并行 DP</td><td>batch</td><td>吞吐扩展</td><td>梯度同步</td></tr><tr><td>张量并行 TP</td><td>层内矩阵</td><td>单层放不下一张卡</td><td>高频集合通信</td></tr><tr><td>流水线并行 PP</td><td>模型层</td><td>跨设备放置模型</td><td>气泡与调度复杂度</td></tr><tr><td>序列 / 上下文并行 SP/CP</td><td>token 序列</td><td>长上下文显存与计算</td><td>注意力通信与负载均衡</td></tr></tbody></table><p>MoE 进一步通过专家并行获得“大参数量、稀疏激活”，代价是 AllToAll 通信和路由不均。实际训练通常组合多种并行方式，目标不是策略越多越好，而是在显存、通信、气泡与工程复杂度之间找到可运行点。</p><h2 id="显存与计算优化" tabindex="-1">显存与计算优化 <a class="header-anchor" href="#显存与计算优化" aria-label="Permalink to “显存与计算优化”">​</a></h2><ul><li><strong>ZeRO</strong> 分阶段切分优化器状态、梯度和参数，降低单卡冗余。</li><li><strong>Flash Attention</strong> 用分块与重计算减少 HBM 往返，是 I/O 感知优化而不只是公式改写。</li><li><strong>混合精度</strong> 用更低精度提升吞吐，但需要缩放、累加精度和数值稳定性保障。</li><li><strong>流水线调度</strong> 通过微批次和虚拟阶段减少气泡，但会增加通信和调度复杂度。</li></ul><h2 id="后训练-反馈信号决定可学到什么" tabindex="-1">后训练：反馈信号决定可学到什么 <a class="header-anchor" href="#后训练-反馈信号决定可学到什么" aria-label="Permalink to “后训练：反馈信号决定可学到什么”">​</a></h2><p>SFT 适合注入明确示范；RLHF / PPO 用奖励模型优化偏好；DPO 把偏好优化转为更直接的对比目标；GRPO 通过组内相对奖励减少对独立价值模型的依赖。选择算法前应先确认：奖励是否可验证、是否足够稠密、训练是否会损伤已有能力。</p><p>低秩微调（LoRA 及变体）适合在有限资源下调整模型，但它解决的是参数更新成本，不会自动解决数据质量、评估或部署隔离问题。</p><h2 id="推理-prefill-与-decode-是两种负载" tabindex="-1">推理：Prefill 与 Decode 是两种负载 <a class="header-anchor" href="#推理-prefill-与-decode-是两种负载" aria-label="Permalink to “推理：Prefill 与 Decode 是两种负载”">​</a></h2><p>Prefill 对输入 token 并行计算，通常更偏计算密集；Decode 每步生成一个 token，频繁读取权重与 KV Cache，更容易受到内存带宽和调度影响。长上下文与高并发下，两阶段的资源争用会更加明显。</p><h3 id="关键技术对应的瓶颈" tabindex="-1">关键技术对应的瓶颈 <a class="header-anchor" href="#关键技术对应的瓶颈" aria-label="Permalink to “关键技术对应的瓶颈”">​</a></h3><table tabindex="0"><thead><tr><th>技术</th><th>主要解决</th></tr></thead><tbody><tr><td>KV Cache</td><td>避免重复计算历史 token</td></tr><tr><td>PagedAttention</td><td>降低 KV Cache 碎片并支持灵活调度</td></tr><tr><td>Continuous Batching</td><td>动态合并不同生命周期的请求</td></tr><tr><td>Ring Attention / Ulysses</td><td>扩展长序列并行</td></tr><tr><td>量化</td><td>降低权重与激活的存储、带宽成本</td></tr><tr><td>知识蒸馏</td><td>将大模型能力迁移到更小模型</td></tr></tbody></table><h2 id="评估不能只看一个数字" tabindex="-1">评估不能只看一个数字 <a class="header-anchor" href="#评估不能只看一个数字" aria-label="Permalink to “评估不能只看一个数字”">​</a></h2><p>推理系统至少同时记录：首 token 延迟、逐 token 延迟、端到端延迟、吞吐、并发、显存占用和失败率。离线单请求最快的实现，在动态批处理或尾延迟约束下未必是线上最优。</p><p>训练评估也需要区分：新任务能力、原有能力保持、训练稳定性和真实成本。只有训练 loss 下降不能证明模型更可用。</p><h2 id="来源" tabindex="-1">来源 <a class="header-anchor" href="#来源" aria-label="Permalink to “来源”">​</a></h2><ul><li><a href="https://app.notion.com/p/04-33b3a54bd6b48140ac71d14f9a1e84d2" target="_blank" rel="noreferrer">Notion：04 大模型训练</a></li><li><a href="https://app.notion.com/p/05-33b3a54bd6b4819db93fdf38f949cd21" target="_blank" rel="noreferrer">Notion：05 大模型推理</a></li></ul>',19)])])}const f=a(n,[["render",i]]);export{b as __pageData,f as default};
